def sequential_search(array, element):
    """
    This function performs a sequential search on the given array for the specified element.

    Args:
        array (list): The list to be searched.
        element: The element to be searched for.

    Returns:
        tuple: A tuple containing a boolean indicating whether the element was found and its index position (or -1 if not found).
    """
    # Initialize the index position to -1, assuming the element is not found
    first_index = -1
    last_index = -1

    # Check if the list is empty
    if not array:
        return (False, -1)

    # Iterate over the array with the enumerate function to get both the index and value of each element
    for index, value in enumerate(array):

        # Check if the current value matches the target element
        if value == element:

            # If a match is found for the first time, update the first and last index position
            if first_index == -1:
                first_index = index
                last_index = index
            # If a match is found for the last time, update the last index position
            else:
                last_index = index

    # If the element is not found, return False and the index position
    if first_index == -1:
        return (False, -1)
    # If the element is found, return True and the index positions
    else:
        return (True, first_index, last_index)
```
